from lib import *
B = dict(mcq_b=3, text_b=4, match_b=3)
def mk(name, o, b, t, m):
    return Topic(name, **B, order=o, bank=b, gap=b, text=t, mcq=m, match=b)
def lv(i,n): return "B1.1" if i < n//2 else "B1.2"
